// Merge Anime Life Sim page translations into the main resources
(['tr', 'en', 'ja', 'fr'] as const).forEach((lng) => {
  if (resources[lng] && resources[lng].translation) {
    Object.assign(resources[lng].translation, animeLifeSimTranslations[lng]);
    Object.assign(resources[lng].translation, adminTranslations[lng]);
  }
});

const HTML_LANG: Record<string, string> = { tr: 'tr', en: 'en', ja: 'ja', fr: 'fr' };
const syncHtmlLang = (lng?: string) => {
  if (typeof document === 'undefined') return;
  const base = (lng || 'en').split('-')[0].toLowerCase();
  document.documentElement.lang = HTML_LANG[base] || 'en';
};

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources,
    fallbackLng: 'en',
    supportedLngs: ['tr', 'en', 'ja', 'fr'],
    nonExplicitSupportedLngs: true,
    interpolation: {
      escapeValue: false, // not needed for react as it escapes by default
    }
  })
  .then(() => syncHtmlLang(i18n.language));

i18n.on('languageChanged', (lng) => syncHtmlLang(lng));

export default i18n;

